import { createRequire } from "module"; const { chromium } = createRequire("<project>/flare/node_modules/")("playwright-core");
const b = await chromium.launch({ channel: "chrome" });
const c = await b.newContext({ viewport:{width:390,height:844}, hasTouch:true, isMobile:true, deviceScaleFactor:2, extraHTTPHeaders:{"x-flare-test":"1"}, permissions:[] });
await c.storageState().catch(()=>{});
const p = await c.newPage();
p.on("console", m=>{ if(m.type()==="error") console.log("CONSOLE ERR", m.text())});
await p.goto("https://flare-outside.onrender.com/app/", {waitUntil:"networkidle", timeout:90000});
for (let i=0;i<5;i++){ const n=p.getByRole("button",{name:/^Next$|^Done$|^Start$|Get started/}); if(await n.count()&&await n.first().isVisible()){await n.first().tap(); await p.waitForTimeout(700); await p.screenshot({path:`onb-${i}.png`}); console.log("--step",i,"\n",await p.innerText("body"));} else break; }
await p.waitForTimeout(1000);
await p.screenshot({path:"app-main.png"});
console.log("=== MAIN\n", await p.innerText("body"));
console.log(await p.$$eval("button, a, input, [role=button], textarea", es=>es.map(e=>e.tagName+" "+(e.type||"")+" | "+(e.innerText||e.getAttribute("aria-label")||e.placeholder||"").trim().replace(/\n/g," / ")+" | vis="+(e.offsetParent!==null)).join("\n")));
await c.storageState({path:"host-state.json"});
await b.close();
EOF
node app2.mjs

