import { createRequire } from "module"; export const { chromium } = createRequire("<project>/flare/node_modules/")("playwright-core");
export async function open(dir, vp={width:390,height:844}){
  const c = await chromium.launchPersistentContext(dir,{ channel:"chrome", viewport:vp, hasTouch:true, isMobile:true, deviceScaleFactor:2, extraHTTPHeaders:{"x-flare-test":"1"} });
  const p = c.pages()[0] || await c.newPage();
  p.on("console", m=>{ if(m.type()==="error"||m.type()==="warning") console.log("CONSOLE", m.type(), m.text())});
  p.on("pageerror", e=>console.log("PAGEERR", e.message));
  return {c,p};
}
export async function dump(p){
  console.log(await p.innerText("body"));
  console.log("--controls--\n"+await p.$$eval("button, a, input, [role=button], textarea, select", es=>es.filter(e=>e.offsetParent!==null||e.type==="file").map(e=>{const r=e.getBoundingClientRect();return e.tagName+" "+(e.type||"")+" | "+(e.innerText||e.getAttribute("aria-label")||e.placeholder||e.value||"").trim().replace(/\n/g," / ")+` | y=${Math.round(r.top)} h=${Math.round(r.height)}`}).join("\n")));
}
EOF
cat > s3.mjs <<'EOF'
import {open,dump} from "./lib.mjs";
const {c,p}=await open("host-profile");
await p.goto("https://flare-outside.onrender.com/app/",{waitUntil:"networkidle",timeout:90000});
await p.getByRole("button",{name:"Skip"}).tap().catch(()=>{});
await p.waitForTimeout(800);
await p.fill("input[type=text]","Test");
await p.getByRole("button",{name:"Continue"}).tap();
await p.waitForTimeout(2000);
await p.screenshot({path:"host-home.png"});
await dump(p);
await c.close();
EOF
node s3.mjs

